import type { BankQuestion } from "@/lib/bank";

/** Time, Speed and Distance (Quantitative Aptitude): 135 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-tsd-1","question":"72 km/h is equal to:","options":["18 m/s","20 m/s","25 m/s","36 m/s"],"answer":1,"explanation":"72 × 5/18 = 20 m/s.","difficulty":"easy"},
  {"id":"quant-tsd-2","question":"A 150 m long train passes a pole in 9 seconds. Its speed is:","options":["50 km/h","54 km/h","60 km/h","72 km/h"],"answer":2,"explanation":"150 ÷ 9 = 50/3 m/s; × 18/5 = 60 km/h.","difficulty":"moderate"},
  {"id":"quant-tsd-3","question":"Trains 120 m and 180 m long run in opposite directions at 40 km/h and 50 km/h. How long do they take to cross each other?","options":["10 seconds","12 seconds","15 seconds","18 seconds"],"answer":1,"explanation":"Relative speed = 90 km/h = 25 m/s; distance = 300 m; time = 12 s.","difficulty":"hard"},
  {"id":"quant-tsd-4","question":"A boat goes 24 km downstream in 2 hours and returns upstream in 3 hours. What is the speed of the stream?","options":["1 km/h","2 km/h","3 km/h","4 km/h"],"answer":1,"explanation":"Downstream 12 km/h, upstream 8 km/h; stream = (12 − 8) ÷ 2 = 2 km/h.","difficulty":"very-hard"},
  {"id":"quant-tsd-5","question":"A man walking at 5 km/h covers 2.5 km in:","options":["25 minutes","30 minutes","40 minutes","50 minutes"],"answer":1,"explanation":"Time = 2.5/5 = 0.5 hour = 30 minutes.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-6","question":"A 200 m long train running at 72 km/h passes a man standing on the platform in:","options":["10 s","20 s","12 s","8 s"],"answer":0,"explanation":"72 km/h = 20 m/s; time = 200/20 = 10 s.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-7","question":"A 240 m long train crosses a 360 m long platform in 30 seconds. Its speed is:","options":["54 km/h","60 km/h","72 km/h","80 km/h"],"answer":2,"explanation":"Distance = 240 + 360 = 600 m in 30 s = 20 m/s = 72 km/h. Using only the platform length gives 43.2 km/h.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-8","question":"A car covers the first half of a distance at 40 km/h and the second half at 60 km/h. Its average speed is:","options":["45 km/h","48 km/h","52 km/h","50 km/h"],"answer":1,"explanation":"Equal distances: 2 × 40 × 60/(40 + 60) = 4,800/100 = 48 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-9","question":"Walking at 3/4 of his usual speed a man reaches office 10 minutes late. His usual time is:","options":["30 minutes","20 minutes","45 minutes","40 minutes"],"answer":0,"explanation":"At 3/4 speed the time becomes 4/3 of usual; the extra 1/3 of the usual time = 10 min, so the usual time = 30 min.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-10","question":"A boat's speed in still water is 10 km/h and the stream flows at 2 km/h. The total time to go 24 km downstream and return is:","options":["4.8 hours","5 hours","6 hours","4 hours"],"answer":1,"explanation":"Downstream 24/12 = 2 h; upstream 24/8 = 3 h; total 5 h. 4.8 h wrongly uses 10 km/h both ways.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-tsd-11","question":"Two trains start at the same time from P and Q, 450 km apart, towards each other at 40 km/h and 50 km/h. When they meet, the faster train has travelled how much more than the slower?","options":["25 km","45 km","50 km","60 km"],"answer":2,"explanation":"They meet after 450/90 = 5 h, having covered 200 km and 250 km, a difference of 50 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-12","question":"A bus averages 60 km/h excluding stoppages and 45 km/h including stoppages. For how many minutes per hour does it stop?","options":["15 minutes","20 minutes","12 minutes","10 minutes"],"answer":0,"explanation":"Each hour it loses 15 km, which takes 15/60 h = 15 minutes at the running speed.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-13","question":"A train crosses a pole in 12 seconds and a 300 m long platform in 27 seconds. The length of the train is:","options":["300 m","240 m","200 m","360 m"],"answer":1,"explanation":"Speed = L/12 = (L + 300)/27 → 27L = 12L + 3,600 → L = 240 m.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-14","question":"A boat takes 5 hours to go 30 km upstream and 3 hours to come back. Its speed in still water is:","options":["10 km/h","2 km/h","6 km/h","8 km/h"],"answer":3,"explanation":"Upstream speed 6 km/h, downstream 10 km/h. Still-water speed = (6 + 10)/2 = 8 km/h; the stream is 2 km/h.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-15","question":"A thief running at 10 km/h has a 100 m head start when a policeman starts chasing him at 12 km/h. The policeman catches him in:","options":["3 minutes","6 minutes","4 minutes","5 minutes"],"answer":0,"explanation":"Relative speed 2 km/h; gap 0.1 km; time = 0.1/2 h = 0.05 h = 3 minutes.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-16","question":"A and B run on a circular track of 600 m in the same direction at 6 m/s and 4 m/s from the same point. They first meet again after:","options":["150 s","60 s","120 s","300 s"],"answer":3,"explanation":"Same direction: relative speed 2 m/s; A must gain one full lap of 600 m, taking 300 s. (In opposite directions it would be 600/10 = 60 s.)","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-tsd-17","question":"Two trains, each 120 m long, run at 60 km/h and 48 km/h in the same direction. The faster train takes how long to pass the slower one completely?","options":["72 s","60 s","8 s","36 s"],"answer":0,"explanation":"Relative speed 12 km/h = 10/3 m/s; distance = 240 m; time = 240 ÷ 10/3 = 72 s. 8 s is the opposite-direction answer.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-18","question":"A man covers 60 km at a uniform speed. Had his speed been 3 km/h more, he would have taken 1 hour less. His speed is:","options":["10 km/h","12 km/h","9 km/h","15 km/h"],"answer":1,"explanation":"60/v − 60/(v + 3) = 1 → 180 = v² + 3v → v² + 3v − 180 = 0 → (v + 15)(v − 12) = 0 → v = 12 km/h.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-tsd-19","question":"A boat goes 15 km upstream and returns to the starting point in 4 hours. If the stream flows at 2 km/h, the speed of the boat in still water is:","options":["10 km/h","7.5 km/h","6 km/h","8 km/h"],"answer":3,"explanation":"15/(b − 2) + 15/(b + 2) = 4 → 30b = 4(b² − 4) → 2b² − 15b − 8 = 0 → (2b + 1)(b − 8) = 0 → b = 8 km/h. Check: 15/6 + 15/10 = 2.5 + 1.5 = 4 h.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-20","question":"A starts from P towards Q at 8 am at 20 km/h. B starts from Q towards P at 9 am at 30 km/h. If P and Q are 170 km apart, they meet at:","options":["11 am","1 pm","12 noon","11:30 am"],"answer":2,"explanation":"By 9 am A has covered 20 km, leaving 150 km. Closing speed 50 km/h gives 3 more hours, so they meet at 12 noon.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-21","question":"A 200 m long train passes a man running at 6 km/h in the same direction in 12 seconds. The speed of the train is:","options":["54 km/h","60 km/h","66 km/h","72 km/h"],"answer":2,"explanation":"Relative speed = 200/12 m/s = 50/3 m/s = 60 km/h. Train speed = 60 + 6 = 66 km/h (same direction adds the man's speed back).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-22","question":"How many of the following statements are correct?\n1. For equal distances covered at speeds u and v, the average speed is 2uv/(u + v).\n2. 1 m/s equals 3.6 km/h.\n3. A train crossing a platform travels a distance equal to its own length only.\n4. Downstream speed minus upstream speed equals twice the speed of the stream.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1, 2 and 4 are true. 3 is false: it travels its own length plus the platform's length. Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-tsd-23","question":"A car goes from A to B at 60 km/h and returns at 40 km/h, taking 5 hours in all. The distance between A and B is:","options":["240 km","100 km","150 km","120 km"],"answer":3,"explanation":"Average speed = 2 × 60 × 40/100 = 48 km/h; total distance = 48 × 5 = 240 km, so one way = 120 km. Check: 2 h + 3 h = 5 h.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-tsd-24","question":"A train leaves a station at 60 km/h. Two hours later a second train leaves the same station in the same direction at 90 km/h. The second train overtakes the first at a distance from the station of:","options":["180 km","240 km","300 km","360 km"],"answer":3,"explanation":"Gap after 2 h = 120 km; closing speed 30 km/h; catch-up time 4 h; distance = 90 × 4 = 360 km.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "quant-tsd-25", "question": "Convert 15 m/s into km/h.", "options": ["4.17 km/h", "54 km/h", "45 km/h", "60 km/h"], "answer": 1, "explanation": "Multiply by 18/5: 15 × 18/5 = 54 km/h. 4.17 comes from dividing by 3.6 instead of multiplying.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-tsd-26", "question": "A 300 m long train passes a pole in 15 seconds. How long will it take to cross a 450 m long bridge?", "options": ["37.5 s", "22.5 s", "30 s", "45 s"], "answer": 0, "explanation": "Speed = 300/15 = 20 m/s. To cross the bridge it covers 300 + 450 = 750 m: 750/20 = 37.5 s. 22.5 s forgets the train's own length.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-tsd-27", "question": "A car covers one-third of a distance at 20 km/h and the rest at 40 km/h. What is its average speed for the whole journey?", "options": ["33⅓ km/h", "26⅔ km/h", "35 km/h", "30 km/h"], "answer": 3, "explanation": "Take the distance as 120 km: 40 km at 20 km/h takes 2 h and 80 km at 40 km/h takes 2 h. Average = 120 ÷ 4 = 30 km/h. 33⅓ km/h averages the speeds by distance, which is wrong.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-tsd-28", "question": "Two trains start at the same time towards each other from stations A and B. After meeting, the faster train reaches its destination in 4 hours and the slower in 9 hours. If the faster train runs at 54 km/h, what is the speed of the slower one?", "options": ["24 km/h", "81 km/h", "36 km/h", "40 km/h"], "answer": 2, "explanation": "Speed ratio = √(time of slower after meeting : time of faster) = √(9/4) = 3 : 2. Slower = 54 × 2/3 = 36 km/h. 24 km/h uses 9 : 4 without the square root.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-tsd-29", "question": "A man rows 40 km downstream in 4 hours and 24 km upstream in 4 hours. How long will he take to row 36 km downstream and come back?", "options": ["9 hours", "9.6 hours", "8 hours", "10.4 hours"], "answer": 1, "explanation": "Downstream speed = 10 km/h, upstream = 6 km/h. Time = 36/10 + 36/6 = 3.6 + 6 = 9.6 hours. 9 hours uses the still-water speed 8 km/h both ways.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-tsd-30", "question": "Walking at 5 km/h a student reaches school 6 minutes late; walking at 6 km/h he is 4 minutes early. How far is the school?", "options": ["5 km", "6 km", "4 km", "3 km"], "answer": 0, "explanation": "Time difference = 10 min = 1/6 h. d/5 − d/6 = d/30 = 1/6 → d = 5 km. 1 km comes from taking 2 minutes as the gap.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-tsd-31", "question": "A train passes a man standing on a platform in 8 seconds and passes the whole 180 m platform in 20 seconds. What are the train's length and speed?", "options": ["144 m; 54 km/h", "120 m; 45 km/h", "96 m; 43.2 km/h", "120 m; 54 km/h"], "answer": 3, "explanation": "L = 8v and L + 180 = 20v, so 180 = 12v → v = 15 m/s = 54 km/h and L = 8 × 15 = 120 m.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-tsd-32", "question": "A and B start together from the same point on a 1.2 km circular track and run in opposite directions at 15 km/h and 21 km/h. After how long do they first meet, and after how long do they first meet at the starting point?", "options": ["2 min; 12 min", "4.8 min; 24 min", "2 min; 24 min", "3 min; 24 min"], "answer": 2, "explanation": "Opposite directions: relative speed 36 km/h, so first meeting after 1.2/36 h = 2 min. Lap times: A 1.2/15 h = 24/5 min, B 1.2/21 h = 24/7 min. LCM = LCM(24, 24)/HCF(5, 7) = 24 min at the start.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-tsd-33", "question": "A thief steals a car at 1:30 pm and drives away at 40 km/h. The theft is discovered at 2:00 pm and the owner chases him at 50 km/h from the same place. When does he catch the thief?", "options": ["3:30 pm", "4:00 pm", "4:30 pm", "3:00 pm"], "answer": 1, "explanation": "In 30 minutes the thief is 20 km ahead. Relative speed = 10 km/h, so catching up takes 2 hours: 2:00 pm + 2 h = 4:00 pm.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-tsd-34", "question": "Two trains 140 m and 160 m long run on parallel tracks. Going the same way, the faster passes the slower in 30 seconds; going opposite ways, they cross in 10 seconds. What are their speeds?", "options": ["72 km/h and 36 km/h", "60 km/h and 30 km/h", "20 km/h and 10 km/h", "90 km/h and 54 km/h"], "answer": 0, "explanation": "Total length 300 m. Difference of speeds = 300/30 = 10 m/s; sum = 300/10 = 30 m/s. So 20 m/s and 10 m/s = 72 km/h and 36 km/h. '20 and 10 km/h' forgets to convert from m/s.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-tsd-35", "question": "A cyclist covers 9 km in 45 minutes. What is his speed in km/h?", "options": ["10 km/h", "12 km/h", "15 km/h", "11.25 km/h"], "answer": 1, "explanation": "45 minutes = 3/4 hour, so speed = 9 ÷ 3/4 = 12 km/h.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-tsd-36", "question": "How far does a car travel in 2 hours 15 minutes at 48 km/h?", "options": ["96 km", "112 km", "108 km", "103.2 km"], "answer": 2, "explanation": "2 h 15 min = 2.25 h, so distance = 48 × 2.25 = 108 km. Reading 2 h 15 min as 2.15 h gives 103.2 km.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-tsd-37", "question": "Two cars take times in the ratio 3 : 4 to cover the same distance. What is the ratio of their speeds?", "options": ["4 : 3", "3 : 4", "16 : 9", "9 : 16"], "answer": 0, "explanation": "For a fixed distance, speed is inversely proportional to time, so the speeds are 4 : 3.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-tsd-38", "question": "Two cyclists start from the same point at the same time and ride in opposite directions at 12 km/h and 18 km/h. How far apart are they after 2 hours 20 minutes?", "options": ["14 km", "66 km", "70 km", "60 km"], "answer": 2, "explanation": "They separate at 12 + 18 = 30 km/h; in 7/3 hours that is 70 km. 14 km uses the difference of speeds, which applies to the same direction.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-tsd-39", "question": "A 360 m long train passes a man walking at 6 km/h in the opposite direction in 18 seconds. What is the speed of the train?", "options": ["78 km/h", "60 km/h", "66 km/h", "72 km/h"], "answer": 2, "explanation": "Relative speed = 360/18 = 20 m/s = 72 km/h. In opposite directions this is train + man, so the train runs at 72 − 6 = 66 km/h.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-tsd-40", "question": "By increasing his speed by 25%, a man reaches his office 12 minutes earlier than usual. What is his usual time?", "options": ["50 minutes", "60 minutes", "75 minutes", "48 minutes"], "answer": 1, "explanation": "Speed × 5/4 means time × 4/5, so he saves 1/5 of the usual time: usual time = 12 × 5 = 60 minutes.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-tsd-41", "question": "A boat goes 30 km downstream in 2 hours. Its speed in still water is 12 km/h. How long will it take to return upstream?", "options": ["3 h 20 min", "2 h 30 min", "3 h", "4 h"], "answer": 0, "explanation": "Downstream speed = 15 km/h, so the stream = 3 km/h and upstream speed = 9 km/h. Time = 30/9 = 3 1/3 h = 3 h 20 min.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-tsd-42", "question": "A car travels at 50 km/h for 3 hours and then at 70 km/h for 2 hours. What is its average speed for the whole journey?", "options": ["58.33 km/h", "58 km/h", "60 km/h", "56 km/h"], "answer": 1, "explanation": "Distance = 150 + 140 = 290 km in 5 hours, so the average = 58 km/h. 60 km/h is the simple average of the speeds, valid only for equal times.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-tsd-43", "question": "Two trains, each 150 m long, take 10 seconds and 15 seconds respectively to pass a pole. How long will they take to cross each other when running in opposite directions?", "options": ["12.5 seconds", "12 seconds", "25 seconds", "6 seconds"], "answer": 1, "explanation": "Speeds are 15 m/s and 10 m/s. Crossing in opposite directions: total length 300 m at relative speed 25 m/s takes 12 seconds.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-tsd-44", "question": "A train crosses a 150 m long platform in 15 seconds and a 250 m long platform in 20 seconds. What is the length of the train?", "options": ["150 m", "250 m", "200 m", "100 m"], "answer": 0, "explanation": "The extra 100 m of platform takes 5 more seconds, so speed = 20 m/s. In 15 s the train covers 300 m = L + 150, so L = 150 m.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-tsd-45", "question": "A runs 1½ times as fast as B. If A gives B a start of 30 m, they reach the winning post together. How long is the race?", "options": ["120 m", "90 m", "45 m", "60 m"], "answer": 1, "explanation": "In the same time A runs L and B runs L − 30, so L/(L − 30) = 3/2, giving L = 90 m.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-46", "question": "In a 1 km race, A beats B by 40 m or by 8 seconds. How long does A take to run the race?", "options": ["192 seconds", "208 seconds", "180 seconds", "200 seconds"], "answer": 0, "explanation": "B covers the last 40 m in 8 s, so B runs 5 m/s and takes 200 s for 1,000 m. A finishes 8 s earlier, in 192 seconds.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-47", "question": "A boat takes twice as long to go a certain distance upstream as to cover the same distance downstream. What is the ratio of the boat's speed in still water to the speed of the stream?", "options": ["3 : 2", "1 : 3", "3 : 1", "2 : 1"], "answer": 2, "explanation": "Downstream speed is twice the upstream speed: b + s = 2(b − s), so b = 3s and the ratio is 3 : 1.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-48", "question": "A train overtakes two people walking in the same direction as the train at 2 km/h and 4 km/h in 9 seconds and 10 seconds respectively. What is the length of the train?", "options": ["60 m", "72 m", "45 m", "50 m"], "answer": 3, "explanation": "9(v − 2) = 10(v − 4) gives v = 22 km/h. Length = (22 − 2) km/h × 9 s = 20 × 5/18 × 9 = 50 m.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-49", "question": "A car covers four successive 3 km stretches at 10 km/h, 20 km/h, 30 km/h and 60 km/h. What is its average speed over the 12 km?", "options": ["25 km/h", "24 km/h", "30 km/h", "20 km/h"], "answer": 3, "explanation": "Time = 3/10 + 3/20 + 3/30 + 3/60 = 0.3 + 0.15 + 0.1 + 0.05 = 0.6 h, so the average = 12/0.6 = 20 km/h. 30 km/h is the simple average of the speeds.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-50", "question": "A, B and C start together from the same point on a 1.2 km circular track and run in the same direction at 4 km/h, 6 km/h and 8 km/h. After how many minutes will they all be together at the starting point for the first time?", "options": ["24 minutes", "36 minutes", "18 minutes", "72 minutes"], "answer": 1, "explanation": "Their lap times are 1.2/4 = 0.3 h = 18 min, 12 min and 9 min. LCM(18, 12, 9) = 36 minutes.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-51", "question": "A boat covers 48 km upstream and 72 km downstream in 12 hours, and 72 km upstream and 48 km downstream in 13 hours. What is the speed of the stream?", "options": ["3 km/h", "1.5 km/h", "4 km/h", "2 km/h"], "answer": 3, "explanation": "Let u = 1/upstream speed, v = 1/downstream speed: 48u + 72v = 12 and 72u + 48v = 13. Adding gives u + v = 5/24, subtracting gives u − v = 1/24, so upstream = 8 and downstream = 12 km/h. Stream = (12 − 8)/2 = 2 km/h.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-tsd-52", "question": "A man takes 60 seconds to be carried up a moving escalator standing still, and 40 seconds to walk up it when it is not moving. How long will he take to walk up the escalator while it is moving?", "options": ["24 seconds", "30 seconds", "50 seconds", "20 seconds"], "answer": 0, "explanation": "Per second he covers 1/40 of it by walking and 1/60 by the escalator, together 1/24, so he takes 24 seconds. 50 s is the average of the two times.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-53", "question": "How many of the following statements are correct?\n1. 1 km/h = 5/18 m/s.\n2. For equal times spent at speeds u and v, the average speed is (u + v)/2.\n3. A train passing a pole covers a distance equal to its own length.\n4. If a boat's upstream speed is u and downstream speed is d, the stream's speed is (d + u)/2.", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 3 are true. 4 is false: (d + u)/2 is the boat's speed in still water; the stream's speed is (d − u)/2.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-54", "question": "Two trains start at the same time from stations A and B, 360 km apart, towards each other, and meet after 3 hours. The faster train completes its journey 2 hours 30 minutes before the slower one. What is the speed of the faster train?", "options": ["80 km/h", "75 km/h", "72 km/h", "60 km/h"], "answer": 2, "explanation": "Sum of speeds = 360/3 = 120 km/h. With speeds 72 and 48, the journey times are 5 h and 7.5 h, a difference of 2.5 h. (From 360/(120 − x) − 360/x = 2.5, x² + 168x − 17,280 = 0 gives x = 72.)", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-tsd-55", "question": "In a 500 m race A beats B by 50 m, and in a 500 m race B beats C by 25 m. By how many metres will A beat C in a 500 m race?", "options": ["70 m", "75 m", "77.5 m", "72.5 m"], "answer": 3, "explanation": "When A runs 500, B runs 450; when B runs 500, C runs 475, so when B runs 450, C runs 450 × 0.95 = 427.5. A beats C by 72.5 m. Adding 50 + 25 = 75 is the trap.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-tsd-56", "question": "A man rows to a place 48 km away and back in 14 hours. He finds that he can row 4 km with the stream in the same time as 3 km against it. What is the speed of the stream?", "options": ["1.5 km/h", "0.5 km/h", "2 km/h", "1 km/h"], "answer": 3, "explanation": "Downstream : upstream speed = 4 : 3, say 4k and 3k. 48/(4k) + 48/(3k) = 28/k = 14, so k = 2: speeds 8 and 6 km/h. Stream = (8 − 6)/2 = 1 km/h.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-tsd-57", "question": "One hour after starting, a train has a breakdown and continues at 3/4 of its former speed, arriving 1.5 hours late. Had the breakdown occurred 60 km further on, it would have arrived only 1 hour late. What is the length of the journey?", "options": ["240 km", "220 km", "200 km", "180 km"], "answer": 1, "explanation": "At 3/4 speed, a stretch x takes x/(3v) extra time. So (D − v)/(3v) = 1.5 and (D − v − 60)/(3v) = 1. Subtracting: 60/(3v) = 0.5, so v = 40 km/h and D − 40 = 180, D = 220 km.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-58", "question": "A and B run round a circular track in opposite directions, starting together from the same point, with speeds in the ratio 3 : 2. At how many distinct points on the track will they meet?", "options": ["1", "6", "3", "5"], "answer": 3, "explanation": "In opposite directions the number of distinct meeting points is the sum of the ratio terms in lowest form, 3 + 2 = 5. (In the same direction it would be 3 − 2 = 1.)", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-59", "question": "Assertion (A): Two trains, each 100 m long, running in the same direction at 50 km/h and 40 km/h, take 72 seconds to pass each other completely.\nReason (R): For bodies moving in the same direction, the relative speed is the difference of their speeds.", "options": ["Both A and R are true, and R is the correct explanation of A", "A is false but R is true", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false"], "answer": 0, "explanation": "Relative speed = 10 km/h = 25/9 m/s and the distance is 200 m, so the time is 200 × 9/25 = 72 s. A is computed exactly by using R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-60", "question": "A man covers 34 km in 4 hours, partly on foot at 5 km/h and the rest by cycle at 15 km/h. How far does he cycle?", "options": ["24 km", "13 km", "17 km", "21 km"], "answer": 3, "explanation": "w + c = 34 and w/5 + c/15 = 4, i.e. 3w + c = 60. Subtracting, 2w = 26, so w = 13 km and c = 21 km.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-61", "question": "Buses leave a depot at regular intervals in both directions along a road and all run at the same speed. A man walking along the road meets an oncoming bus every 10 minutes and is overtaken by a bus every 15 minutes. At what interval do the buses leave the depot?", "options": ["12 minutes", "12.5 minutes", "10 minutes", "15 minutes"], "answer": 0, "explanation": "Let the gap between buses be d. d/(b + w) = 10 and d/(b − w) = 15, so 2b = d/10 + d/15 = d/6 and b = d/12. The buses are 12 minutes apart (the harmonic mean of 10 and 15). 12.5 is the simple average.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-tsd-62", "question": "A train running at 54 km/h passes a motorcyclist coming from the opposite direction at 18 km/h in 9 seconds. At the same speed, it crosses a platform in 30 seconds. How long is the platform?", "options": ["300 m", "180 m", "270 m", "330 m"], "answer": 2, "explanation": "Relative speed = 72 km/h = 20 m/s, so the train is 20 × 9 = 180 m long. At 15 m/s it covers 450 m in 30 s, so the platform is 450 − 180 = 270 m.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-tsd-63", "question": "Car X leaves P for Q, 300 km away, at 9 am. Car Y leaves Q for P at 10 am. They meet at 1 pm at a point 180 km from P. What is Y's speed?", "options": ["30 km/h", "40 km/h", "45 km/h", "60 km/h"], "answer": 1, "explanation": "Y has covered 300 − 180 = 120 km between 10 am and 1 pm, i.e. in 3 hours, so its speed is 40 km/h. Dividing by 4 hours (30 km/h) uses X's travel time.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-tsd-64", "question": "Walking at 4/5 of his usual speed, a man is 15 minutes late. How early will he be if he walks at 5/4 of his usual speed?", "options": ["12 minutes", "10 minutes", "18.75 minutes", "15 minutes"], "answer": 0, "explanation": "At 4/5 speed the time is 5/4 of usual, so the extra 1/4 = 15 minutes and the usual time is 60 minutes. At 5/4 speed he takes 48 minutes, i.e. 12 minutes early.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-65","question":"A car covers 540 m in 18 seconds. What is its speed in km/h?","options":["30 km/h","108 km/h","100 km/h","120 km/h"],"answer":1,"explanation":"Speed = 540/18 = 30 m/s, and 30 × 18/5 = 108 km/h.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-tsd-66","question":"A train covers 285 km in 3 hours 48 minutes. What is its average speed?","options":["75 km/h","76 km/h","74 km/h","80 km/h"],"answer":0,"explanation":"3 h 48 min = 3.8 h. Speed = 285 ÷ 3.8 = 75 km/h. Reading 48 minutes as 0.48 h is the trap.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-67","question":"The speeds of two cyclists are in the ratio 4 : 5. If the faster one takes 40 minutes for a ride, how long does the slower one take for the same ride?","options":["32 minutes","45 minutes","60 minutes","50 minutes"],"answer":3,"explanation":"For the same distance, time is inversely proportional to speed: 40 × 5/4 = 50 minutes.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-tsd-68","question":"An athlete runs 5 laps of a 400 m track in 12 minutes. What is his speed in km/h?","options":["12 km/h","2 km/h","10 km/h","9 km/h"],"answer":2,"explanation":"Distance = 2 km in 12 min = 0.2 h. Speed = 2 ÷ 0.2 = 10 km/h.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-69","question":"Thunder is heard 6 seconds after a lightning flash. If sound travels at 330 m/s, how far away was the lightning?","options":["1.8 km","2.2 km","1.98 km","0.55 km"],"answer":2,"explanation":"Distance = 330 × 6 = 1,980 m = 1.98 km (light arrives almost instantly).","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-tsd-70","question":"A bus covers 210 km in 3.5 hours. At the same speed, how long will it take to cover 330 km?","options":["5 hours","5.5 hours","6 hours","5.25 hours"],"answer":1,"explanation":"Speed = 60 km/h, so 330 km takes 330/60 = 5.5 hours.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-tsd-71","question":"A man walks the 2.4 km between two stations in 20 minutes. What is his speed in km/h?","options":["7.2 km/h","8 km/h","12 km/h","4.8 km/h"],"answer":0,"explanation":"20 min = 1/3 h, so speed = 2.4 × 3 = 7.2 km/h.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-72","question":"A boat moves at 15 km/h in still water and the stream flows at 3 km/h. What is its speed downstream?","options":["12 km/h","15 km/h","9 km/h","18 km/h"],"answer":3,"explanation":"Downstream the stream helps: 15 + 3 = 18 km/h (upstream it would be 12 km/h).","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-tsd-73","question":"A 180 m long train running at 54 km/h crosses a bridge in 40 seconds. How long is the bridge?","options":["600 m","360 m","400 m","420 m"],"answer":3,"explanation":"54 km/h = 15 m/s. In 40 s the train covers 600 m = train + bridge, so the bridge = 600 − 180 = 420 m.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-74","question":"A man covers a distance in 2 hours at 30 km/h. At what speed must he travel to cover it in 1.5 hours?","options":["45 km/h","35 km/h","40 km/h","37.5 km/h"],"answer":2,"explanation":"Distance = 60 km. In 1.5 hours he needs 60/1.5 = 40 km/h.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-75","question":"Two cars start from the same point at the same time and travel in opposite directions at 45 km/h and 55 km/h. How far apart are they after 2 hours 24 minutes?","options":["224 km","240 km","250 km","24 km"],"answer":1,"explanation":"They separate at 45 + 55 = 100 km/h. 2 h 24 min = 2.4 h, so 240 km. Their difference in speed (10 km/h) would give only 24 km.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-tsd-76","question":"A car covers 35 km in the first hour and its speed increases by 2 km/h every hour after that. How far does it travel in 12 hours?","options":["552 km","420 km","546 km","564 km"],"answer":0,"explanation":"Distances form an AP: 35, 37, …, 57. Sum = 12 × (35 + 57)/2 = 552 km.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-77","question":"A boat that moves at 20 km/h in still water covers 48 km downstream in 2 hours. What is its speed upstream?","options":["16 km/h","24 km/h","12 km/h","18 km/h"],"answer":0,"explanation":"Downstream speed = 24 km/h, so the stream = 4 km/h and upstream = 20 − 4 = 16 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-78","question":"A man walks 4 km in 50 minutes and then cycles 11 km in 40 minutes. What is his average speed for the whole trip?","options":["12.6 km/h","9.5 km/h","11 km/h","10 km/h"],"answer":3,"explanation":"Total = 15 km in 90 min = 1.5 h, so 10 km/h. Averaging the two speeds (4.8 and 16.5) is wrong.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-tsd-79","question":"A 250 m long train running at 66 km/h passes through a 300 m long tunnel. How long does it take to clear the tunnel completely?","options":["16.4 seconds","13.6 seconds","30 seconds","25 seconds"],"answer":2,"explanation":"Distance = 250 + 300 = 550 m; speed = 66 × 5/18 = 55/3 m/s. Time = 550 × 3/55 = 30 s.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-80","question":"The speeds of A and B are in the ratio 3 : 4, and A takes 30 minutes more than B to cover a certain distance. How long does B take?","options":["120 minutes","90 minutes","60 minutes","40 minutes"],"answer":1,"explanation":"Times are in the ratio 4 : 3; the difference of 1 part = 30 min. B takes 3 parts = 90 minutes.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-81","question":"In a 100 m race, A beats B by 10 m. What is the ratio of their speeds?","options":["9 : 10","10 : 9","11 : 10","10 : 1"],"answer":1,"explanation":"When A runs 100 m, B runs 90 m in the same time. Speeds are 100 : 90 = 10 : 9.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-82","question":"A rider travels at 15 km/h for 40 minutes and then covers 12 km at 18 km/h. What is his average speed?","options":["16.5 km/h","16 km/h","17 km/h","15.5 km/h"],"answer":0,"explanation":"First leg: 10 km in 40 min; second: 12 km in 40 min. Total 22 km in 80 min = 22 × 60/80 = 16.5 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-83","question":"A man travels half a distance by bus at 60 km/h and the other half on foot at 6 km/h, taking 5.5 hours in all. What is the total distance?","options":["66 km","55 km","72 km","60 km"],"answer":3,"explanation":"Time = d/120 + d/12 = 11d/120 = 5.5, so d = 60 km.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-84","question":"A truck's speed is 3/5 of a car's speed. The car covers 450 km in 6 hours. How far will the truck go in 5 hours?","options":["270 km","250 km","225 km","375 km"],"answer":2,"explanation":"Car = 75 km/h, so truck = 45 km/h. In 5 hours: 225 km.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-85","question":"Two trains 180 m and 120 m long, running in opposite directions, cross each other in 12 seconds. If one runs at 40 km/h, what is the speed of the other?","options":["90 km/h","60 km/h","50 km/h","45 km/h"],"answer":2,"explanation":"Relative speed = 300/12 = 25 m/s = 90 km/h. The other train runs at 90 − 40 = 50 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-86","question":"A car goes from P to Q at 40 km/h and its average speed for the round trip is 48 km/h. What was its speed from Q to P?","options":["56 km/h","60 km/h","52 km/h","64 km/h"],"answer":1,"explanation":"2 × 40 × v/(40 + v) = 48 gives 80v = 1,920 + 48v, so v = 60 km/h. 56 km/h assumes the simple average.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-87","question":"A man fires a gun facing a cliff and hears the echo 3 seconds later. If sound travels at 340 m/s, how far is the cliff?","options":["510 m","1,020 m","340 m","680 m"],"answer":0,"explanation":"Sound goes to the cliff and back: 2d = 340 × 3 = 1,020 m, so d = 510 m.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-88","question":"Fog cuts a train's speed to 80% of normal, and a 240 km run takes 1 hour longer. What is its normal speed?","options":["48 km/h","75 km/h","80 km/h","60 km/h"],"answer":3,"explanation":"At 80% speed the time is 1.25 times normal, so the extra 0.25 × normal time = 1 h, giving normal time 4 h and speed 240/4 = 60 km/h.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-89","question":"A swimmer covers 2 km against the current in 40 minutes and returns in 20 minutes. What is the speed of the current?","options":["3 km/h","4.5 km/h","1 km/h","1.5 km/h"],"answer":3,"explanation":"Upstream = 2/(2/3) = 3 km/h; downstream = 2/(1/3) = 6 km/h. Current = (6 − 3)/2 = 1.5 km/h.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-90","question":"A covers a distance in 4 hours and B in 6 hours. They start at the same time from opposite ends and walk towards each other. What fraction of the distance has A covered when they meet?","options":["2/3","2/5","3/5","1/2"],"answer":2,"explanation":"Speeds are in the ratio 1/4 : 1/6 = 3 : 2, so A covers 3/5 of the distance.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-91","question":"The speeds of three cars are in the ratio 2 : 3 : 4. What is the ratio of the times they take to cover the same distance?","options":["4 : 3 : 2","6 : 4 : 3","2 : 3 : 4","3 : 4 : 6"],"answer":1,"explanation":"Times ∝ 1/speed: 1/2 : 1/3 : 1/4 = 6 : 4 : 3 (multiplying by 12).","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-tsd-92","question":"A man must cover 15 km in 1.5 hours. He walks the first 5 km at 5 km/h. At what speed must he cover the rest?","options":["20 km/h","10 km/h","15 km/h","12 km/h"],"answer":0,"explanation":"The walk takes 1 hour, leaving 0.5 hour for 10 km: 20 km/h.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-tsd-93","question":"A train passes a 120 m platform in 18 seconds and a man walking at 6 km/h in the same direction in 12 seconds. How long is the train?","options":["200 m","180 m","240 m","150 m"],"answer":1,"explanation":"With speed v m/s: L + 120 = 18v and L = 12(v − 5/3). So 18v − 120 = 12v − 20, v = 50/3 m/s (60 km/h) and L = 300 − 120 = 180 m.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-94","question":"Train A (150 m) passes a pole in 10 seconds and train B (200 m) passes it in 8 seconds. How long will they take to cross each other when running in opposite directions?","options":["8.75 seconds","9 seconds","35 seconds","10 seconds"],"answer":0,"explanation":"Speeds: 150/10 = 15 m/s and 200/8 = 25 m/s. Opposite directions: 350/(15 + 25) = 8.75 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-95","question":"A 300 m long train overtakes a cyclist riding at 18 km/h in 30 seconds. How long will it take to pass a car coming towards it at 36 km/h?","options":["15 seconds","20 seconds","10 seconds","12 seconds"],"answer":3,"explanation":"Relative speed with the cyclist = 10 m/s, so the train runs at 10 + 5 = 15 m/s. With the car: 15 + 10 = 25 m/s, so 300/25 = 12 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-96","question":"Car P leaves a town at 9:00 am at 40 km/h. Car Q leaves the same town on the same road at 9:30 am at 50 km/h, and car R at 10:00 am at 60 km/h. Which car does R overtake first, and when?","options":["Q, at 12:30 pm","P, at 12:30 pm","P, at 12 noon","Q, at 12 noon"],"answer":2,"explanation":"At 10 am P is 40 km ahead and Q 25 km ahead. R gains 20 km/h on P (2 h, i.e. 12 noon) but only 10 km/h on Q (2.5 h, 12:30 pm). So P is overtaken first, at noon.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-97","question":"A 200 m long train passes a 300 m platform in 25 seconds. How long will it take to pass a 150 m long train coming from the opposite direction at 54 km/h?","options":["7 seconds","17.5 seconds","10 seconds","14 seconds"],"answer":2,"explanation":"Train speed = 500/25 = 20 m/s; the other runs at 15 m/s. Relative speed 35 m/s, distance 350 m, so 10 s.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-98","question":"A boat's speed in still water is three times the stream's speed. It covers 32 km downstream in 2 hours. How long will it take to go 24 km upstream?","options":["2 hours","3 hours","4 hours","1.5 hours"],"answer":1,"explanation":"Downstream = 4s = 16 km/h, so s = 4 and the boat = 12 km/h. Upstream = 8 km/h, so 24 km takes 3 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-99","question":"At 40 km/h a train reaches its destination 11 minutes late; at 50 km/h it is only 5 minutes late. How long is the journey?","options":["20 km","25 km","30 km","16 km"],"answer":0,"explanation":"The two times differ by 6 minutes: d/40 − d/50 = d/200 = 1/10 h, so d = 20 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-100","question":"A motorcycle leaves town A for town B at 9 am at 40 km/h. A car leaves A at 10 am at 60 km/h and reaches B one hour before the motorcycle. How far is B from A?","options":["180 km","200 km","120 km","240 km"],"answer":3,"explanation":"If the motorcycle takes t hours, the car takes t − 2 (it starts 1 h later and arrives 1 h earlier). 40t = 60(t − 2) gives t = 6, so the distance is 240 km.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-101","question":"A train passes a standing man in 18 seconds and a man walking towards it at 6 km/h in 16 seconds. What is the speed of the train?","options":["54 km/h","45 km/h","60 km/h","48 km/h"],"answer":3,"explanation":"Length = 18v = 16(v + 5/3), so 2v = 80/3 and v = 40/3 m/s = 48 km/h (train length 240 m).","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-102","question":"A car's speed is 80% of a train's speed. The car starts 30 minutes before the train from the same place, and the train catches it 2 hours after starting, 160 km from the start. What is the car's speed?","options":["80 km/h","60 km/h","64 km/h","72 km/h"],"answer":2,"explanation":"The car has been driving 2.5 hours when caught, so its speed = 160/2.5 = 64 km/h (and the train's 160/2 = 80 km/h, consistent with 80%).","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-103","question":"With a tailwind a plane covers 1,200 km in 2 hours; against the same wind it takes 2.5 hours. What is the wind speed?","options":["120 km/h","60 km/h","40 km/h","540 km/h"],"answer":1,"explanation":"Speeds: 600 km/h with the wind and 480 km/h against. Wind = (600 − 480)/2 = 60 km/h (plane 540 km/h).","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-tsd-104","question":"Car A is 20% faster than car B. B leaves first, and A follows 30 minutes later on the same road, catching B 180 km from the start. What is A's speed?","options":["72 km/h","60 km/h","75 km/h","80 km/h"],"answer":0,"explanation":"B drives t hours and A t − 0.5 at 1.2 times the speed: t = 1.2(t − 0.5), so t = 3. B = 60 km/h and A = 180/2.5 = 72 km/h.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-105","question":"A train covers 420 km in 8 hours, including 6 halts of 10 minutes each. What is its average speed while running?","options":["60 km/h","52.5 km/h","56 km/h","65 km/h"],"answer":0,"explanation":"Halts take 60 minutes, so running time = 7 hours. 420/7 = 60 km/h. 52.5 km/h includes the halts.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-tsd-106","question":"Two trains whose lengths are in the ratio 3 : 2 run in opposite directions at 54 km/h and 36 km/h, and cross each other in 12 seconds. How long is the longer train?","options":["120 m","150 m","200 m","180 m"],"answer":3,"explanation":"Relative speed = 90 km/h = 25 m/s, so the lengths add to 300 m. Longer = 3/5 × 300 = 180 m.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-107","question":"A car covers 60 km in the first hour, and its speed drops by 5 km/h every hour after that. How far does it go in 6 hours?","options":["300 km","270 km","285 km","330 km"],"answer":2,"explanation":"60 + 55 + 50 + 45 + 40 + 35 = 285 km (an AP: 6 × (60 + 35)/2).","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-108","question":"A rectangular field is 80 m by 60 m. By walking along the diagonal instead of along two adjacent sides, by what percent does a person shorten the walk?","options":["40%","28.57%","20%","25%"],"answer":1,"explanation":"Two sides = 140 m; the diagonal = √(80² + 60²) = 100 m. Saving = 40/140 ≈ 28.57%.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-109","question":"A man sitting in a train running at 72 km/h sees a 280 m long goods train going the other way pass him in 9 seconds. What is the speed of the goods train?","options":["112 km/h","40 km/h","48 km/h","32 km/h"],"answer":1,"explanation":"Relative speed = 280/9 m/s = 112 km/h. Goods train = 112 − 72 = 40 km/h. Only the goods train's length matters, as the man is a point.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-110","question":"A boat goes 40 km upstream in 8 hours and 36 km downstream in 6 hours. What is the speed of the stream?","options":["0.5 km/h","1 km/h","5.5 km/h","1.5 km/h"],"answer":0,"explanation":"Upstream = 5 km/h, downstream = 6 km/h. Stream = (6 − 5)/2 = 0.5 km/h; boat = 5.5 km/h.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-111","question":"A man can row three times as fast downstream as upstream. What is the ratio of his speed in still water to the speed of the stream?","options":["3 : 1","1 : 2","4 : 1","2 : 1"],"answer":3,"explanation":"Take upstream 1 and downstream 3: boat = (3 + 1)/2 = 2 and stream = (3 − 1)/2 = 1. Ratio 2 : 1.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-112","question":"A man walks from A to B at 5 km/h and cycles back at 15 km/h, taking 1 hour 20 minutes in all. How far is A from B?","options":["6 km","4 km","5 km","7.5 km"],"answer":2,"explanation":"d/5 + d/15 = 4d/15 = 4/3, so d = 5 km.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-tsd-113","question":"A sets out walking at 4 km/h. Four hours later B starts cycling after him from the same point at 12 km/h. How far from the start does B catch A?","options":["16 km","20 km","24 km","32 km"],"answer":2,"explanation":"A's lead = 16 km; B gains 8 km/h, so he takes 2 hours and is 24 km from the start.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-tsd-114","question":"A car averages 60 km/h on a journey. Had it gone 10 km/h faster, it would have taken 1 hour less. How long is the journey?","options":["360 km","420 km","600 km","480 km"],"answer":1,"explanation":"d/60 − d/70 = d/420 = 1, so d = 420 km.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-115","question":"Two motorcyclists start from the same crossing at the same time, one going north at 30 km/h and the other east at 40 km/h. How far apart are they after 2 hours?","options":["100 km","140 km","20 km","50 km"],"answer":0,"explanation":"After 2 hours they are 60 km and 80 km from the crossing at right angles: √(60² + 80²) = 100 km.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-116","question":"Two cyclists 60 km apart ride towards each other at 12 km/h and 18 km/h. A bee starts from one cyclist and flies at 40 km/h back and forth between them until they meet. How far does the bee fly in all?","options":["80 km","60 km","40 km","120 km"],"answer":0,"explanation":"The cyclists meet after 60/30 = 2 hours. The bee flies non-stop for those 2 hours: 40 × 2 = 80 km. No need to add up the legs.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-tsd-117","question":"Two people start from opposite ends of a 30 km road at the same time, walking towards each other at 4 km/h and 6 km/h. Each walks to the far end and immediately turns back. When do they meet for the second time?","options":["6 hours after starting","3 hours after starting","12 hours after starting","9 hours after starting"],"answer":3,"explanation":"By the first meeting they cover 30 km together (3 h). By the second meeting they cover 3 × 30 = 90 km together, which takes 9 hours.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-tsd-118","question":"A man rowing upstream drops his hat into the river. He notices 10 minutes later, turns round and rows downstream at the same rowing effort. How long after turning does he reach the hat?","options":["20 minutes","It depends on the stream's speed","10 minutes","5 minutes"],"answer":2,"explanation":"In the water's frame the hat is still and the man rows away and back at the same speed, so he returns in the same 10 minutes. The stream's speed cancels out.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-tsd-119","question":"A boat's speed in still water is 9 km/h. It takes 3 hours longer to go 36 km upstream than to go 36 km downstream. What is the speed of the stream?","options":["4 km/h","3 km/h","2 km/h","4.5 km/h"],"answer":1,"explanation":"36/(9 − s) − 36/(9 + s) = 72s/(81 − s²) = 3, so s² + 24s − 81 = 0 and s = 3 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-120","question":"A car covers the three equal thirds of a journey at x, 2x and 3x km/h. If its average speed is 36 km/h, what is x?","options":["18","22","24","20"],"answer":1,"explanation":"Average = 3/(1/x + 1/2x + 1/3x) = 3x/(11/6) = 18x/11 = 36, so x = 22.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-tsd-121","question":"Car A takes 2 hours more than car B to cover 360 km. If A doubled its speed, it would take 1 hour less than B. What is B's speed?","options":["90 km/h","60 km/h","120 km/h","72 km/h"],"answer":0,"explanation":"Let A take x hours and B y hours: x − y = 2 and y − x/2 = 1. So x/2 = 3, x = 6 and y = 4. B's speed = 360/4 = 90 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-122","question":"A boat that moves at 15 km/h in still water goes 36 km upstream, halts for 1 hour and returns. The whole trip takes 6 hours. What is the speed of the stream?","options":["2 km/h","4 km/h","5 km/h","3 km/h"],"answer":3,"explanation":"Moving time = 5 h: 36/(15 − s) + 36/(15 + s) = 1,080/(225 − s²) = 5, so 225 − s² = 216 and s = 3 km/h.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-123","question":"Train P passes a pole in 9 seconds and train Q in 12 seconds. Running in opposite directions, they cross each other in 10.5 seconds. What is the ratio of their speeds?","options":["4 : 3","3 : 4","1 : 1","3 : 2"],"answer":2,"explanation":"Lengths are 9a and 12b. (9a + 12b)/(a + b) = 10.5 gives 1.5b = 1.5a, so a = b. Their speeds are equal; only the lengths differ.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-tsd-124","question":"A train leaves X at 6 am and reaches Y at 12 noon. Another train leaves Y at 8 am and reaches X at 11 am. At what time do they meet?","options":["9:00 am","9:40 am","9:20 am","10:00 am"],"answer":2,"explanation":"Speeds are D/6 and D/3. By 8 am the first train has done D/3, leaving 2D/3, closed at D/6 + D/3 = D/2 per hour: 4/3 h = 1 h 20 min. They meet at 9:20 am.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-125","question":"A and B start at the same time from P and Q towards each other. After meeting, A takes 4 hours to reach Q and B takes 9 hours to reach P. If A's speed is 36 km/h, how far apart are P and Q?","options":["300 km","360 km","324 km","216 km"],"answer":1,"explanation":"Speeds are in the ratio √9 : √4 = 3 : 2, so B = 24 km/h. Time to meet = √(4 × 9) = 6 h. PQ = 6 × (36 + 24) = 360 km.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-126","question":"On a 2 km circular track, A runs three times as fast as B in the same direction, both starting together from the same point. By the time A completes 6 rounds, how many times has he overtaken B?","options":["4","6","2","3"],"answer":0,"explanation":"When A runs 6 rounds, B runs 2. A overtakes B once for every extra lap he gains: 6 − 2 = 4 times.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-tsd-127","question":"A train is held up for 30 minutes at a station. To arrive on time, it raises its speed by 10 km/h for the remaining 150 km. What was its original speed?","options":["60 km/h","40 km/h","45 km/h","50 km/h"],"answer":3,"explanation":"150/v − 150/(v + 10) = 1/2 gives v(v + 10) = 3,000, so v = 50 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-128","question":"Because of a signal problem a train runs at 20% below its usual speed and reaches 18 minutes late on a 120 km run. What is its usual speed?","options":["80 km/h","120 km/h","96 km/h","100 km/h"],"answer":3,"explanation":"At 80% speed the time is 1.25 times usual, so 0.25 × usual time = 18 min and usual time = 72 min = 1.2 h. Speed = 120/1.2 = 100 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-tsd-129","question":"A boatman rows 12 km downstream and back in 3 hours 12 minutes. If the stream flows at 2 km/h, what is his speed in still water?","options":["6 km/h","10 km/h","8 km/h","9 km/h"],"answer":2,"explanation":"12/(b + 2) + 12/(b − 2) = 3.2. Trying b = 8: 12/10 + 12/6 = 1.2 + 2 = 3.2 ✓.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-130","question":"Two friends set out together from P for Q, 24 km away, at 4 km/h and 6 km/h. The faster one reaches Q, turns back at once and meets the other. How far from Q do they meet?","options":["4 km","4.8 km","6 km","5.2 km"],"answer":1,"explanation":"Together they cover 2 × 24 = 48 km by the meeting, at 10 km/h combined: 4.8 hours. The slower one has walked 19.2 km, so they meet 4.8 km from Q.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-131","question":"Two cars start together from the same point on a 6 km circular track and run in the same direction at 36 km/h and 54 km/h. How many times does the faster car pass the slower one in 2 hours?","options":["6","5","18","3"],"answer":0,"explanation":"The faster car gains 18 km/h, i.e. 36 km in 2 hours = 6 laps of the track. Each lap gained is one pass, so 6 times.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-tsd-132","question":"On a 400 m track, A runs at 8 m/s and B at 5 m/s in the same direction, starting together. How far has B run when A laps him for the first time?","options":["666.67 m","400 m","1,066.67 m","500 m"],"answer":0,"explanation":"A gains 3 m/s and needs 400 m to lap B: 400/3 s. B runs 5 × 400/3 ≈ 666.67 m in that time.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-tsd-133","question":"A river is 300 m wide and flows at 3 km/h. A swimmer who swims at 5 km/h in still water heads straight across. How far downstream does he land?","options":["300 m","500 m","240 m","180 m"],"answer":3,"explanation":"Crossing time = 0.3 km ÷ 5 km/h = 0.06 h. In that time the current carries him 3 × 0.06 = 0.18 km = 180 m downstream.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-tsd-134","question":"In a 200 m race, A can give B a start of 20 m and C a start of 32 m. How much start can B give C over 200 m?","options":["12 m","14 m","13.33 m","10.67 m"],"answer":2,"explanation":"While A runs 200, B runs 180 and C 168. So when B runs 200, C runs 200 × 168/180 = 186.67 m. B can give C about 13.33 m.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-tsd-135","question":"A car's wheel has a radius of 35 cm and turns 600 times a minute. What is the car's speed? (Take π = 22/7.)","options":["39.6 km/h","79.2 km/h","132 km/h","75.6 km/h"],"answer":1,"explanation":"Circumference = 2 × 22/7 × 0.35 = 2.2 m. Distance per minute = 2.2 × 600 = 1,320 m = 79.2 km/h.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
];

export default questions;
